  'Media Law and Ethics',
  'This course prepares students to make legally informed and ethically defensible decisions in journalism, public relations, advertising, entertainment, digital platforms, and AI-mediated media. It covers topics including access law, source protection, platform governance, and a professional case-memo practicum.',
  $mlaejson${"slug": "media-law-and-ethics", "title": "Media Law and Ethics", "description": "This course prepares students to make legally informed and ethically defensible decisions in journalism, public relations, advertising, entertainment, digital platforms, and AI-mediated media. It covers topics including access law, source protection, platform governance, and a professional case-memo practicum.", "topics": [{"id": "2223537b-dcf9-4f66-a7bb-73e600e65b74", "type": "topic", "title": "First Amendment foundations", "description": "Establishes the constitutional logic behind speech, press freedom, public discourse, and limits on government regulation.", "children": [{"id": "fbc6486b-69b4-4c22-8684-051041674cbc", "type": "subtopic", "title": "Speech and press clauses", "children": [{"id": "47ae325f-1d59-4b0a-8c9c-07868bdf8244", "type": "concept", "title": "Core text of the First Amendment"}, {"id": "0f6a7605-aad0-42cf-9f36-f86a689b469c", "type": "concept", "title": "Government action requirement"}, {"id": "bf5d1325-6870-41e6-878c-6497cff647af", "type": "concept", "title": "Speech, press, assembly, and petition relationships"}], "description": "Students learn why media law begins with constitutional protection for expression and publication."}, {"id": "7f8aae40-d263-465a-8122-b67a60501b06", "type": "subtopic", "title": "Levels of scrutiny and categories of speech", "children": [{"id": "8823e8ba-b2a6-4395-b60f-fa91b46c76db", "type": "concept", "title": "Content-based and content-neutral rules"}, {"id": "d92e34ea-25e9-45ae-9a1b-8d55afb13e99", "type": "concept", "title": "Protected and less-protected speech"}, {"id": "6accb480-38a8-4f6c-ab7f-09d7773eef86", "type": "concept", "title": "Time, place, and manner limits"}], "description": "Legal analysis depends on what kind of speech is regulated and why."}, {"id": "f994ed5f-faf0-4282-9ea1-f986c168ce8f", "type": "subtopic", "title": "Press freedom and democratic accountability", "children": [{"id": "d9afffb5-05e7-49f0-8970-e9cb24595f24", "type": "concept", "title": "Watchdog role"}, {"id": "3f91c850-abd4-4b19-8f27-0337d30e2596", "type": "concept", "title": "Public debate"}, {"id": "997c2148-8c2a-46be-85d4-1511f737fd6c", "type": "concept", "title": "Chilling effects"}], "description": "The point is not only individual liberty; it is public oversight, dissent, and self-government."}]}, {"id": "7f8bb107-22d8-4679-90e0-e4f800f1bd3c", "type": "topic", "title": "Prior restraint and censorship", "description": "Explains why stopping publication before it happens is treated as one of the most serious threats to free expression.", "children": [{"id": "ff0029a0-8057-49db-854b-3fe9f9cad520", "type": "subtopic", "title": "Prior restraint doctrine", "children": [{"id": "362f89f0-58ca-4ddd-b82a-b93067fc3696", "type": "concept", "title": "Injunctions"}, {"id": "597b2545-2db0-4e49-8276-a111354ee0d8", "type": "concept", "title": "Licensing schemes"}, {"id": "ade24e05-e2c1-4ea9-96d6-70411c9607c1", "type": "concept", "title": "National security claims"}], "description": "Students learn the difference between punishment after publication and government suppression before publication."}, {"id": "2cb0346d-a9c9-441f-9cc2-568b41ef960a", "type": "subtopic", "title": "Censorship in schools, workplaces, and platforms", "children": [{"id": "22f8482d-645b-4cbc-a069-137b760935c2", "type": "concept", "title": "Student speech"}, {"id": "2d30d2cf-d150-403d-b4bb-056f47101623", "type": "concept", "title": "Employee speech"}, {"id": "344576ff-10cf-4a4e-b361-f7bdfabba663", "type": "concept", "title": "Private moderation versus state action"}], "description": "Censorship questions look different across public institutions, private employers, and platform rules."}, {"id": "f65b2c82-b76d-4dbb-98f9-dbd341494a25", "type": "subtopic", "title": "Legal and ethical responses", "children": [{"id": "019aef21-d1f7-4e5a-ac94-a70aebf36e01", "type": "concept", "title": "Editorial review"}, {"id": "5b66fbbb-52e7-4e44-8b23-6ad38d17881a", "type": "concept", "title": "Legal counsel"}, {"id": "eee60faa-71fe-44f7-b23f-ef6a74c83ccb", "type": "concept", "title": "Transparency and public explanation"}], "description": "Media practitioners need escalation paths when publication is threatened."}]}, {"id": "cee6ee17-0b1f-41d5-917a-66c056c7b3ae", "type": "topic", "title": "Defamation, libel, and slander", "description": "Builds the practical skill of publishing accurate, fair, and legally defensible claims about people and organizations.", "children": [{"id": "6c3b6fb9-20c4-4823-9968-1139af6ffed9", "type": "subtopic", "title": "Elements of defamation", "children": [{"id": "4f66c6dd-f990-44aa-bda6-090335abe691", "type": "concept", "title": "Publication"}, {"id": "13d1c839-c118-4d64-b447-db29364e296d", "type": "concept", "title": "Identification"}, {"id": "64fe6e4c-d790-4c7d-85ef-06063de79c0b", "type": "concept", "title": "Falsity"}, {"id": "b49f6f34-e096-4100-9774-2b75bc6c51fb", "type": "concept", "title": "Fault and damages"}], "description": "Students learn the legal building blocks that turn a false statement into a defamation claim."}, {"id": "75668756-995f-4745-b24b-7b7fa9771582", "type": "subtopic", "title": "Public figures and actual malice", "children": [{"id": "ecb99168-77e5-4498-93f2-b385f93d46b0", "type": "concept", "title": "Public official doctrine"}, {"id": "67b83c9d-cb04-467c-b748-4207d98d06c4", "type": "concept", "title": "Actual malice"}, {"id": "27c2938c-df8f-4609-9497-b65868c75bf6", "type": "concept", "title": "Limited-purpose public figures"}], "description": "The law gives special protection to speech about public officials and public figures."}, {"id": "b27f1c43-0d6f-44ab-8273-45378e55e8b2", "type": "subtopic", "title": "Risk reduction in reporting and communication", "children": [{"id": "9adaa05a-d45b-4eb6-b626-36a2bd74c5b6", "type": "concept", "title": "Verification"}, {"id": "02aaf028-831e-4d4d-aa8b-a0128f37a128", "type": "concept", "title": "Attribution"}, {"id": "dac4be9c-ed29-433a-aa26-b9aa2e2d87b0", "type": "concept", "title": "Fair comment and opinion"}], "description": "Good practice reduces legal risk while improving public trust."}]}, {"id": "1e54c2ad-2401-4952-9937-7489a130a6bf", "type": "topic", "title": "Privacy law and public interest", "description": "Teaches students to balance newsworthiness, consent, dignity, data collection, and audience need to know.", "children": [{"id": "981a90af-cfe2-4649-b10a-e83c82d7dbb3", "type": "subtopic", "title": "Privacy torts", "children": [{"id": "066f3aed-93c5-4e14-9c50-1cdcb72219cf", "type": "concept", "title": "Intrusion"}, {"id": "e5d57bec-e661-4344-b80e-af5e81b8e3d2", "type": "concept", "title": "Public disclosure of private facts"}, {"id": "ddcc5aee-6816-4fcc-b5e4-061228d84eb8", "type": "concept", "title": "False light"}, {"id": "9eae5f13-0d21-41d8-9c1b-14c5f89d40c7", "type": "concept", "title": "Appropriation"}], "description": "Students learn the common privacy claims that affect media and communication practice."}, {"id": "877b82c9-f5ec-4f12-8b67-afed81565857", "type": "subtopic", "title": "Public interest tests", "children": [{"id": "7513c03d-c18a-4457-8131-e23359ad25f2", "type": "concept", "title": "Newsworthiness"}, {"id": "9950eac5-99c7-4485-aa2a-69f1514e2962", "type": "concept", "title": "Proportionality"}, {"id": "3166f5ff-e5eb-4c1e-b22c-54a3add92069", "type": "concept", "title": "Minimizing harm"}], "description": "Not every legally publishable detail is ethically necessary."}, {"id": "6d222870-acc3-4805-a3b0-6eee4a669c49", "type": "subtopic", "title": "Data privacy and surveillance", "children": [{"id": "f41c862c-291b-4861-960b-b63a65dd6929", "type": "concept", "title": "Consent"}, {"id": "f645f3e0-883e-436a-b458-cd1abbac0bab", "type": "concept", "title": "Data minimization"}, {"id": "e03242eb-eba3-4e6e-a8f6-211825a5ee51", "type": "concept", "title": "Sensitive information"}], "description": "Digital communication adds privacy risks around tracking, scraping, targeting, and analytics."}]}, {"id": "37ab5759-8e94-485e-949e-bff6b12308ce", "type": "topic", "title": "Copyright, fair use, and intellectual property", "description": "Prepares students to use, quote, remix, share, and create media without confusing convenience with legal permission.", "children": [{"id": "7ea5a9f9-8f23-4c26-ac58-b4126e610c90", "type": "subtopic", "title": "Copyright basics", "children": [{"id": "1c383ed7-1460-40b1-a2e0-ebd574e0f283", "type": "concept", "title": "Original expression"}, {"id": "f4e4e3e5-53aa-44d6-91a5-d08bd78478bb", "type": "concept", "title": "Ownership and work-for-hire"}, {"id": "96d8b2f4-0db3-43dd-b0f8-d6498d155105", "type": "concept", "title": "Exclusive rights"}], "description": "Students learn what copyright protects, who owns it, and how long rights can last."}, {"id": "01ce7921-7caf-46b7-820c-7b11e3ea55cb", "type": "subtopic", "title": "Fair use and permissions", "children": [{"id": "979abee4-153b-4315-8253-a19e8ea86ae1", "type": "concept", "title": "Purpose and transformation"}, {"id": "b40210a6-1400-4b70-8912-e5a6c962d20b", "type": "concept", "title": "Nature, amount, and market effect"}, {"id": "eeb9e091-3361-4b6e-bf5c-3308f06b4e3b", "type": "concept", "title": "Licensing and clearance"}], "description": "Fair use is a contextual analysis, not a magic phrase."}, {"id": "c8fd2900-38f8-4ed3-b0d3-7f5fed5a8109", "type": "subtopic", "title": "Digital media and creator rights", "children": [{"id": "edec4be3-18f5-4364-a681-b76dc61c2515", "type": "concept", "title": "Creative Commons"}, {"id": "77a872ad-4021-4373-8622-4068c6bcaecb", "type": "concept", "title": "DMCA basics"}, {"id": "25a743ec-ea43-4b73-931c-7b39fe8e3ba6", "type": "concept", "title": "Attribution and takedown workflows"}], "description": "Modern media work involves user-generated content, memes, embeds, archives, and AI training debates."}]}, {"id": "20d83c1a-05d7-4fe1-90f0-8e11e7e7cb54", "type": "topic", "title": "Access to information, FOIA, and reporter protections", "description": "Adds the access-to-records and source-protection skills needed for public-interest reporting and accountability communication.", "children": [{"id": "235038e1-ea99-4f70-bf76-9cc3dc11fe69", "type": "subtopic", "title": "Public records and open meetings", "children": [{"id": "4f36e781-dbff-4edc-b620-cf973881fd1e", "type": "concept", "title": "FOIA basics"}, {"id": "e846b598-72b7-4309-8670-684f377f6e0f", "type": "concept", "title": "State public records laws"}, {"id": "919eb76a-8f94-47be-bb21-e9934ac830e0", "type": "concept", "title": "Open meetings and exemptions"}], "description": "Access law helps journalists and communicators obtain evidence about public institutions."}, {"id": "1b9cc4dc-5d27-4cc2-9ac2-7d97aa35100c", "type": "subtopic", "title": "Reporters privilege and subpoenas", "children": [{"id": "0fb8e2df-9d9d-40fd-b0ad-5b1cb9400bb1", "type": "concept", "title": "Shield laws"}, {"id": "327f91d0-56a3-44c8-a3ff-c3fe1306f4c6", "type": "concept", "title": "Confidential sources"}, {"id": "24e4dae4-0587-4098-96f6-a07b80f0e608", "type": "concept", "title": "Subpoena response basics"}], "description": "Students learn how source protection works and where it is legally fragile."}, {"id": "f6161977-4fc5-4b7a-983b-cc8e37008e9f", "type": "subtopic", "title": "Ethics of access and source protection", "children": [{"id": "81614d34-d7c4-4ec4-92e4-e90b900146be", "type": "concept", "title": "Anonymity standards"}, {"id": "90bb9798-6f2e-4be5-a6b0-81a65ab8f7bc", "type": "concept", "title": "Source motives"}, {"id": "09322e71-4e61-47e1-afcf-1c22bc3e2563", "type": "concept", "title": "Document verification"}], "description": "Legal access must be paired with careful judgment about promises, safety, and public value."}]}, {"id": "46f544f7-53bb-4ccc-809a-5f72cfb4c501", "type": "topic", "title": "Commercial speech and advertising regulation", "description": "Covers the legal and ethical rules that govern advertising, persuasion, endorsements, sponsored content, and consumer protection.", "children": [{"id": "c98ab08d-4502-471d-803c-db93e0b04f2b", "type": "subtopic", "title": "Commercial speech doctrine", "children": [{"id": "81dd4620-2a94-4556-8364-241b8f510d08", "type": "concept", "title": "Truthful versus misleading claims"}, {"id": "06f22316-76ed-4bb6-ad52-f1bd347f1e42", "type": "concept", "title": "Substantial government interest"}, {"id": "173d429f-b89c-4b5c-96ed-01977604d6a7", "type": "concept", "title": "Central Hudson framework"}], "description": "Advertising receives constitutional protection, but it can be regulated more than political speech."}, {"id": "baa7daf0-5340-40d6-901e-7371a3ecfe4d", "type": "subtopic", "title": "FTC and endorsement rules", "children": [{"id": "29a63938-d337-45ad-95a8-350f55b2df5f", "type": "concept", "title": "Material connections"}, {"id": "6428a626-a10d-4ae1-b487-8baab98e6152", "type": "concept", "title": "Substantiation"}, {"id": "fca3e6be-870f-433a-90eb-7c97c77d4315", "type": "concept", "title": "Influencer and creator disclosures"}], "description": "Students learn disclosure duties around ads, influencers, sponsorship, and native advertising."}, {"id": "cff4ac51-6cd4-45ec-9752-11b1fedc157c", "type": "subtopic", "title": "Ethics in persuasion", "children": [{"id": "9caee4fd-89dd-49bd-8569-0b1bc91a907f", "type": "concept", "title": "Dark patterns"}, {"id": "6307b1f6-3715-4cab-bb71-d4fc13015878", "type": "concept", "title": "Targeting vulnerable audiences"}, {"id": "8f077121-86f3-4257-86a3-97a7cde03bde", "type": "concept", "title": "Transparency and consent"}], "description": "Law sets minimums; ethics asks whether persuasion respects autonomy and avoids manipulation."}]}, {"id": "f794dc62-48b5-441f-8302-f489e9261339", "type": "topic", "title": "Broadcast regulation and the FCC", "description": "Explains why broadcast media have historically been regulated differently from print, cable, and digital platforms.", "children": [{"id": "f7298ec1-6ecf-4093-8b2c-f00dc41e32f5", "type": "subtopic", "title": "Spectrum and licensing", "children": [{"id": "e548f429-cba9-4178-8117-86055bba4b3e", "type": "concept", "title": "Scarcity rationale"}, {"id": "3402b880-76cc-4e33-879c-979871ec1be7", "type": "concept", "title": "Public interest standard"}, {"id": "679e78dc-ead5-4b5b-bb8c-6b6d8aeb146f", "type": "concept", "title": "License renewal"}], "description": "Broadcast regulation begins with scarce public spectrum and licensing authority."}, {"id": "74c9d5f0-5a39-44d6-8542-43a1aa7c16bc", "type": "subtopic", "title": "FCC policy areas", "children": [{"id": "e3f99419-f952-4cdf-b531-be60e97eb3cb", "type": "concept", "title": "Ownership and competition"}, {"id": "b83646b9-4fcb-461e-8058-cacd4dd24325", "type": "concept", "title": "Equal opportunities and sponsorship ID"}, {"id": "0ccdf9dd-fd6a-41f3-b0cc-56a0739f24f5", "type": "concept", "title": "Emergency alerts"}], "description": "Students learn how ownership, political broadcasting, children's programming, and emergency rules affect media practice."}, {"id": "c9d53110-24a9-4213-816a-06cf774ace2c", "type": "subtopic", "title": "Broadcast versus digital regulation", "children": [{"id": "db5a0426-1043-4e23-ac38-cc7a1c80d288", "type": "concept", "title": "Cable and streaming distinctions"}, {"id": "b1d67bc8-c003-493e-980e-81828b34639e", "type": "concept", "title": "Platform policy gaps"}, {"id": "eba174a3-649b-4670-b736-bce3da8f95c5", "type": "concept", "title": "Convergence challenges"}], "description": "A world-class course asks whether older regulatory models fit streaming, platforms, and creators."}]}, {"id": "778872d7-33c5-4dbc-a8e3-d785e4460961", "type": "topic", "title": "Indecency, obscenity, and content rules", "description": "Teaches how law draws difficult lines around sexual content, offensive expression, harm, age, context, and community standards.", "children": [{"id": "f65af14c-dca9-42d9-8299-3623bf97149a", "type": "subtopic", "title": "Obscenity doctrine", "children": [{"id": "7bf94d69-d50c-42af-8cc1-4d960a4e9dc4", "type": "concept", "title": "Miller test"}, {"id": "6ef9e965-d153-47bb-8557-8b9b5320c725", "type": "concept", "title": "Community standards"}, {"id": "7593aad4-cde7-45d8-8a12-f5aaa874353e", "type": "concept", "title": "Serious value"}], "description": "Students learn why obscenity can be regulated outside ordinary First Amendment protection."}, {"id": "3154dd1d-8c8d-4576-a357-f5ee9423c665", "type": "subtopic", "title": "Indecency and harmful content", "children": [{"id": "43f91760-00f0-4a2f-b546-7123fb3ae9d8", "type": "concept", "title": "Broadcast indecency"}, {"id": "9f384732-79d6-4bc4-9eac-1642f86efee0", "type": "concept", "title": "Safe harbor"}, {"id": "a41d1c15-0013-4c5c-98ae-1ef86e0d80cc", "type": "concept", "title": "Age-appropriate design debates"}], "description": "Different media systems apply different standards for indecency and child protection."}, {"id": "86089dac-0a7c-48c4-b992-7aa53ee641da", "type": "subtopic", "title": "Ethical editorial judgment", "children": [{"id": "94b68a7f-6728-4954-82ff-fa001f1d3d63", "type": "concept", "title": "Warning labels"}, {"id": "4ac40532-142d-4358-b508-cbc38bdf91fc", "type": "concept", "title": "Graphic imagery"}, {"id": "1e1e960d-7faf-4a0c-97c7-a180a1be731a", "type": "concept", "title": "Trauma and vulnerable audiences"}], "description": "Content rules do not answer every question about dignity, harm, audience, and context."}]}, {"id": "d261411f-67a5-41e9-9ff4-66ddc230cf29", "type": "topic", "title": "Journalism ethics codes and professional standards", "description": "Centers professional ethics as a daily decision practice, not only a list of rules after legal doctrine.", "children": [{"id": "07216fd3-d6ab-44a4-a788-bded6fd1dd2c", "type": "subtopic", "title": "Core ethics principles", "children": [{"id": "0e4dd37a-9708-41a7-add1-6f8f05415c6b", "type": "concept", "title": "Seek truth and report it"}, {"id": "5a3a6cb9-66b1-4bfa-96e2-1f5c438a4309", "type": "concept", "title": "Minimize harm"}, {"id": "eac5e338-1d4f-4f9c-83a5-9760e3e1a49b", "type": "concept", "title": "Act independently"}, {"id": "3270bd96-20a2-46c5-8add-b45fab58d790", "type": "concept", "title": "Be accountable and transparent"}], "description": "Students learn the recurring commitments of journalism and public-interest media."}, {"id": "9a70073b-09a2-4169-874f-3ba221234652", "type": "subtopic", "title": "Verification and accuracy", "children": [{"id": "1d6df181-0b74-4247-a55c-f5aab362678e", "type": "concept", "title": "Fact-checking"}, {"id": "dd879b93-5ba1-4554-bf12-0b803cbb4573", "type": "concept", "title": "Attribution"}, {"id": "7b7e5af7-1e9b-4f9d-97bf-5a1a3a3a98fb", "type": "concept", "title": "Corrections and updates"}], "description": "Truth-telling requires disciplined methods, not only good intentions."}, {"id": "10ecc7e4-3d6a-4c30-b2c6-bfa9580ba5cd", "type": "subtopic", "title": "Independence and conflicts", "children": [{"id": "8693a599-5a6b-4355-a314-dad0193488e7", "type": "concept", "title": "Gifts and relationships"}, {"id": "4268e640-37ff-4ea5-a7aa-c81a245c3ecb", "type": "concept", "title": "Political activity"}, {"id": "310812ae-f76d-4963-aeaf-ce95b5f3306f", "type": "concept", "title": "Sponsored or branded work"}], "description": "Ethical credibility depends on avoiding hidden influence and compromised judgment."}]}, {"id": "0c67842c-23a7-46c6-a130-3f331b509e5a", "type": "topic", "title": "Ethics in advertising, PR, and entertainment", "description": "Broadens the course beyond journalism to the ethical challenges of strategic communication, branded media, entertainment, and advocacy.", "children": [{"id": "18e16769-ab72-469c-8b5e-61953acacc2c", "type": "subtopic", "title": "Strategic communication ethics", "children": [{"id": "2632e796-2f1b-4316-b06c-f4f27cbe9d97", "type": "concept", "title": "PRSA-style values"}, {"id": "dd6fb679-bac4-4e55-9e91-bb1196c10eaa", "type": "concept", "title": "Conflicts of interest"}, {"id": "e83b37a7-f894-4578-a8d7-1c0442ee2e97", "type": "concept", "title": "Truthfulness and selective disclosure"}], "description": "Students examine advocacy, persuasion, disclosure, and stakeholder duty."}, {"id": "a08e0a62-cce5-40a4-a83b-2cf7368268ca", "type": "subtopic", "title": "Entertainment and representation", "children": [{"id": "6595496b-f8d7-4425-9b67-0e4288978b64", "type": "concept", "title": "Stereotypes and inclusion"}, {"id": "0e4a8e5c-b975-4ee7-af28-4ddc34879cdf", "type": "concept", "title": "Harm and dignity"}, {"id": "c11dfdc2-e0f2-4e17-94e6-0eace59c31b0", "type": "concept", "title": "Creative freedom versus responsibility"}], "description": "Media ethics includes how entertainment represents people, communities, violence, and social issues."}, {"id": "e455b2ad-32ae-4fb8-af10-4f2ff0f784f6", "type": "subtopic", "title": "Sponsored and branded content", "children": [{"id": "ead52e87-fb84-4f75-bd56-3cea77618698", "type": "concept", "title": "Native advertising"}, {"id": "71591a68-adf8-4f9e-82e1-445779b25ece", "type": "concept", "title": "Product placement"}, {"id": "4f0fc1b9-8a98-4a07-bc5a-e5e61d200d9e", "type": "concept", "title": "Influencer partnerships"}], "description": "Hybrid content creates special transparency and audience-trust problems."}]}, {"id": "66a483de-772f-4000-808f-eae6efe30877", "type": "topic", "title": "Digital platforms, misinformation, privacy, and AI-generated media", "description": "Makes the course current by addressing platform governance, synthetic media, algorithmic amplification, misinformation, and AI ethics.", "children": [{"id": "a4f3f0b3-027e-437e-a3ec-07431408ff62", "type": "subtopic", "title": "Platform governance and content moderation", "children": [{"id": "f5c0d940-5faa-4aa9-b6a8-2df4666ec2fd", "type": "concept", "title": "Terms of service"}, {"id": "781cdad8-f698-46a5-a70b-5b00595578db", "type": "concept", "title": "Moderation systems"}, {"id": "f2661c6b-7cd3-4070-a00d-c2ff64458075", "type": "concept", "title": "Appeals and transparency"}], "description": "Students learn how private rules shape public speech at massive scale."}, {"id": "8b118e40-9bee-4ea4-a36c-f140a535745c", "type": "subtopic", "title": "Misinformation and verification", "children": [{"id": "7e0d0fef-27b1-49a0-871f-9d1a549660b9", "type": "concept", "title": "Disinformation tactics"}, {"id": "6eca03c8-ac20-4839-b0e5-90bfc930cbd4", "type": "concept", "title": "Verification workflows"}, {"id": "53ee6ffc-83ce-4a9d-bd81-1c951a325cc6", "type": "concept", "title": "Correction and prebunking"}], "description": "Ethical media practice must respond to false, manipulated, or misleading content without amplifying harm."}, {"id": "efe8f0c6-1bbd-4ae0-99aa-0084b3c964a2", "type": "subtopic", "title": "AI and synthetic media", "children": [{"id": "21b87d2d-09d2-4d20-94d1-b412ec543293", "type": "concept", "title": "Deepfakes"}, {"id": "2ba48c3e-83f3-405a-a4a8-e18ed7594fea", "type": "concept", "title": "Synthetic images and voices"}, {"id": "e7e80ff2-0192-4e22-8cf6-d654d7425e2f", "type": "concept", "title": "AI newsroom policies"}], "description": "AI-generated content raises questions of disclosure, authorship, consent, deception, and accountability."}]}, {"id": "c0483ead-b97c-4913-9e1d-a7a5478cb634", "type": "topic", "title": "Professional ethics case memo", "description": "Culminates the course by requiring students to reason through a realistic media-law-and-ethics problem with evidence and judgment.", "children": [{"id": "cdc499b1-923a-4c8c-8939-57b80ce5ce4c", "type": "subtopic", "title": "Case briefing", "children": [{"id": "01f52538-d119-45ff-ba7f-09612f30a6ec", "type": "concept", "title": "Facts and timeline"}, {"id": "d47a2fe9-e4b8-4c24-8fd9-3be8cf568187", "type": "concept", "title": "Stakeholder map"}, {"id": "a77d9d78-073e-4b5a-b91b-29d4d79278d0", "type": "concept", "title": "Legal and ethical questions"}], "description": "Students learn to identify the facts, stakeholders, legal issues, ethical tensions, and missing information."}, {"id": "45135150-6554-4183-a012-a5acd5814c04", "type": "subtopic", "title": "Decision frameworks", "children": [{"id": "f4311dbc-b161-49ae-a225-1c53f5e2abf8", "type": "concept", "title": "Legal risk analysis"}, {"id": "79abc2ea-5fd1-4e79-95bf-631eb74de16b", "type": "concept", "title": "SPJ and professional codes"}, {"id": "e79f0442-e7b3-43fb-b14c-9620d8801871", "type": "concept", "title": "Consequences, duties, and virtues"}], "description": "A good memo makes reasoning visible rather than hiding behind instinct."}, {"id": "eaf64373-ca9d-4672-a7db-8db0b951e688", "type": "subtopic", "title": "Recommendation and accountability plan", "children": [{"id": "271f623a-7a64-41ef-8960-07507cbebd35", "type": "concept", "title": "Recommended action"}, {"id": "c7a3983f-129a-49ff-9f20-7cf5d95806e5", "type": "concept", "title": "Corrections or disclosures"}, {"id": "a7e0e451-1b60-49f3-973b-47bc696102b8", "type": "concept", "title": "Documentation and review"}], "description": "Students practice giving usable advice with caveats, follow-up steps, and public accountability."}]}], "dbBacked": true}$mlaejson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'media-law-and-ethics'
